#!/usr/bin/env bash
# Regenerates tests/fixtures/traces from deterministic throwaway
# repositories (fixed identity, dates and config), so the output is the same
# on every machine. Run from the repository root:
#
#   tests/fixtures/make-traces.sh
#
# then review the diff: a changed fixture means the pipeline changed.
set -euo pipefail
ROOT="$(pwd)"
cargo build --quiet --locked
BIN="$ROOT/target/debug/smart-commit"
OUT="$ROOT/tests/fixtures/traces"
WORK="$(mktemp -d)"
trap 'rm -rf "$WORK"' EXIT
export GIT_CONFIG_GLOBAL=/dev/null GIT_CONFIG_NOSYSTEM=1
export GIT_AUTHOR_NAME=Test GIT_AUTHOR_EMAIL=test@example.com GIT_AUTHOR_DATE=2026-01-01T00:00:00Z
export GIT_COMMITTER_NAME=Test GIT_COMMITTER_EMAIL=test@example.com GIT_COMMITTER_DATE=2026-01-01T00:00:00Z
mkdir -p "$OUT"
fresh() { rm -rf "${WORK:?}/${1:?}"; git init -q --initial-branch=main "$WORK/$1"; cd "$WORK/$1"; }
commit() { git commit -q --allow-empty -m "$1"; }

fresh conventional
for s in "feat(git): coleta o histórico de commits" "fix(diff): corrige o parse de renomeações" "docs: atualiza a documentação da fase 2"; do commit "$s"; done
git checkout -q -b feature/NPU-12-retry
printf 'pub fn retry() -> usize {\n    2\n}\n' > retry.rs; git add retry.rs
"$BIN" --backend mock \
  --mock-response $'Aqui está a mensagem:\n\nAdiciona a nova tentativa' \
  --mock-response $'```\nfeat(generate): adiciona a nova tentativa\n```' \
  --trace "$OUT/conventional-pt-retry.json" >/dev/null

fresh gitmoji
for s in "✨ add login page" "🐛 fix crash on logout" ":memo: update the readme"; do commit "$s"; done
printf '# Login\n\nHow to sign in.\n' > LOGIN.md; printf 'x\n' > Cargo.lock; git add .
"$BIN" --backend mock --mock-response "" --mock-response "<think>still thinking" \
  --trace "$OUT/gitmoji-fallback.json" >/dev/null 2>&1

fresh free
for s in "Add support for renames" "Fix crash when the diff is empty"; do commit "$s"; done
printf 'fn main() {}\n' > main.rs; git add main.rs
"$BIN" --backend mock \
  --mock-response $'<think>The diff adds main.</think>\nSure! Here is a commit message:\n"Add the main entry point."\n\nThis commit message describes the change.' \
  --trace "$OUT/free-en-chatty.json" >/dev/null

# Found in real use: a root config change in a repository whose recent
# history mostly uses one scope (`training`); the trace records where each
# scope's commits went, which the prompt does not show yet (training H4b).
fresh scopes
mkdir -p training src docs
printf 'x\n' > src/main.rs; git add .; commit "feat(cli): add the prompt command"
printf 'x\n' > training/train.py; git add .; commit "feat(training): add the training script"
printf 'x\n' > docs/training.md; git add .; commit "docs(training): record the results"
printf 'y\n' > training/train.py; git add .; commit "fix(training): salt the ranking"
printf '[tools]\nrust = "1.99"\n' > mise.toml; git add mise.toml
"$BIN" --backend mock --mock-response "chore: pin rust 1.99 in mise.toml" \
  --trace "$OUT/conventional-en-scopes.json" >/dev/null

# Found in real use: a new repository with one commit and a one-line change;
# the model repeated the only history subject.
fresh copied
mkdir src; printf 'fn main() {\n    println!("Hello, world!");\n}\n' > src/main.rs; git add .
commit "feat: Add a simple hello world program"
printf 'fn main() {\n    println!("{}", format!("1 + 1 = {}", 2));\n    println!("Hello, world!");\n}\n' > src/main.rs
printf '# This file is automatically @generated by Cargo.\nversion = 4\n' > Cargo.lock; git add .
"$BIN" --backend mock \
  --mock-response "feat: Add a simple hello world program" \
  --mock-response "feat: print the sum of 1 + 1" \
  --trace "$OUT/conventional-en-copied.json" >/dev/null

# Found in real use: only a new Cargo.lock staged; the model saw just its
# name and repeated the history. No model is asked: no mock reply is used.
fresh lockfile
commit "feat: Add a simple hello world program"
printf '# This file is automatically @generated by Cargo.\nversion = 4\n' > Cargo.lock; git add Cargo.lock
"$BIN" --backend mock --trace "$OUT/conventional-en-lockfile.json" >/dev/null

# Found in real use: only a README staged, which names two scripts; the
# model answered `fix` and said the scripts changed.
fresh docs-only
mkdir training
printf 'x\n' > training/build_inputs.py; printf 'x\n' > training/select.py; git add .
commit "feat(training): add the dataset scripts"
printf '# Training\n\nRun build_inputs.py, then select.py.\n' > training/README.md; git add .
commit "docs(training): describe the pipeline"
printf 'y\n' > training/select.py; git add .; commit "fix(training): salt the ranking"
printf '# Training\n\nRun build_inputs.py, then select.py.\n\nThe frozen set needs the build_inputs.py and select.py of 35a1ae8:\n\n    git show 35a1ae8:training/select.py > /tmp/select.py\n' > training/README.md; git add training/README.md
"$BIN" --backend mock --mock-response "fix(training): update build inputs and select scripts" \
  --trace "$OUT/conventional-en-docs-only.json" >/dev/null

# Found in real use: a new section in AGENTS.md; the model answered `fix` and
# reused most of the last history subject, which the exact-copy guard misses.
fresh partial-copy
printf '# AGENTS.md\n\n## Commits\n\nOne purpose per commit.\n' > AGENTS.md; git add .
commit "docs(agents): add the commit rules"
mkdir -p tests/fixtures; printf 'x\n' > tests/fixtures/make-traces.sh; git add .
commit "test(fixtures): trace a docs-only change answered with fix"
printf '# AGENTS.md\n\n## Commits\n\nOne purpose per commit.\n\n### Ask smart-commit first\n\nBefore each commit, run smart-commit on the staged change with --trace\nand compare its message with yours.\n' > AGENTS.md; git add AGENTS.md
"$BIN" --backend mock --mock-response "fix(agents): trace a docs-only change" \
  --trace "$OUT/conventional-en-partial-copy.json" >/dev/null

# Found in real use: a reply one column over the limit; the subject is cut
# at a word boundary and ends mid-sentence ("... to reflect the").
fresh too-long
mkdir docs
printf '# AGENTS.md\n\nModels are never hosted here.\n' > AGENTS.md; printf '# Training\n' > docs/training.md; git add .
commit "docs(agents): add the model rules"
printf '# AGENTS.md\n\nFine-tunes are published on Hugging Face.\n' > AGENTS.md
printf '# Training\n\nPublish smart-commit-1.5b-v1.\n' > docs/training.md; git add .
"$BIN" --backend mock \
  --mock-response "fix(agents): update AGENTS.md and docs/training.md to reflect the changes" \
  --trace "$OUT/conventional-en-too-long.json" >/dev/null

# Found in real use: one subject per file, on consecutive lines; the second
# subject becomes the body.
fresh two-subjects
mkdir docs
printf '# AGENTS.md\n' > AGENTS.md; printf '# Training\n' > docs/training.md; git add .
commit "docs: add AGENTS.md and the training page"
printf '# AGENTS.md\n\nFine-tunes are published on Hugging Face.\n' > AGENTS.md
printf '# Training\n\nPublish smart-commit-1.5b-v1.\n' > docs/training.md; git add .
"$BIN" --backend mock \
  --mock-response $'fix(AGENTS.md): update AGENTS.md with the latest changes\nfix(docs/training.md): update docs/training.md with the latest changes' \
  --trace "$OUT/conventional-en-two-subjects.json" >/dev/null

# Found in real use, with smart-commit-0.5b-v0.1: a root config change in a
# repository whose history is all scoped and never uses `chore`; the model
# kept to the listed types and took the most frequent scope.
fresh closed-types
mkdir -p training docs src
printf 'x\n' > training/export_gguf.py; git add .; commit "feat(training): keep the merged safetensors with export_gguf --merged"
printf 'x\n' > AGENTS.md; git add .; commit "docs(agents): version fine-tunes as v0.x while the recipe changes"
printf 'x\n' > src/models.rs; git add .; commit "feat(model): add the smart-commit-1.5b-v0.1 and 0.5b-v0.1 fine-tunes"
printf 'x\n' > docs/training.md; git add .; commit "docs(training): v0.1 is published and registered, H5 and H6 come next"
printf 'x\n' > training/filter_supported.py; git add .; commit "fix(training): make h3a reproducible with filter_supported.py"
printf '[tools]\nrust = "1.99"\n' > mise.toml; git add mise.toml
"$BIN" --backend mock --mock-response "feat(training): add rust 1.99 to mise.toml" \
  --trace "$OUT/conventional-en-closed-types.json" >/dev/null
# The same change, with smart-commit-1.5b-v0.1: still a listed type, and a
# scope made from the file name.
"$BIN" --backend mock --mock-response "docs(mise): add rust to tools" \
  --trace "$OUT/conventional-en-file-scope.json" >/dev/null

# Found in real use, with smart-commit-0.5b-v0.1: a release's version bump;
# the model answered `feat` and took a model name from the last subject for
# the version.
fresh release
mkdir -p src docs
printf '[package]\nname = "smart-commit"\nversion = "0.4.0"\nedition = "2024"\n' > Cargo.toml
printf '[[package]]\nname = "smart-commit"\nversion = "0.4.0"\n' > Cargo.lock
git add .; commit "chore: release 0.4.0"
printf 'x\n' > docs/roadmap.md; git add .; commit "docs(roadmap): plan a model server that stays up, KV caching and grammars"
printf 'x\n' > AGENTS.md; git add .; commit "docs(agents): publish the project's fine-tunes on Hugging Face"
printf 'y\n' > AGENTS.md; git add .; commit "docs(agents): host the fine-tunes on the LucasBRT Hugging Face account"
printf 'z\n' > AGENTS.md; git add .; commit "docs(agents): version fine-tunes as v0.x while the recipe changes"
printf 'x\n' > src/models.rs; git add .; commit "feat(model): add the smart-commit-1.5b-v0.1 and 0.5b-v0.1 fine-tunes"
sed -i 's/0\.4\.0/0.5.0/' Cargo.toml Cargo.lock; git add Cargo.toml Cargo.lock
"$BIN" --backend mock --mock-response "feat(model): update smart-commit to 0.5b-v0.1" \
  --trace "$OUT/conventional-en-release.json" >/dev/null

# Found in real use, with smart-commit-0.5b-v0.1: a change much like the last
# commit's; the model repeated that commit's subject, and again after the
# retry named it, so the message came from the file list.
fresh copied-twice
mkdir -p tests/fixtures/traces
printf 'x\n' > tests/fixtures/make-traces.sh; git add .; commit "feat(model): add the smart-commit-1.5b-v0.1 and 0.5b-v0.1 fine-tunes"
printf 'y\n' > tests/fixtures/make-traces.sh; printf '{}\n' > tests/fixtures/traces/closed-types.json; git add .
commit "test(fixtures): trace a config change kept to the listed types"
printf 'z\n' > tests/fixtures/make-traces.sh; printf '{}\n' > tests/fixtures/traces/file-scope.json; git add .
"$BIN" --backend mock \
  --mock-response "test(fixtures): trace a config change kept to the listed types" \
  --mock-response "test(fixtures): trace a config change kept to the listed types" \
  --trace "$OUT/conventional-en-copied-twice.json" >/dev/null 2>&1

# Found in real use, with smart-commit-0.5b-v0.2: a fix in a script with its
# regression test; the model answered `test` and described the bug instead
# of the fix.
fresh fix-as-test
mkdir training
printf 'def main():\n    for t in traces:\n        row = {\n            "first_try": t["attempts"][0]["rejected"] is None,\n        }\n' > training/score.py
printf 'def test_releases():\n    pass\n' > training/test_build_inputs.py; git add .
commit "feat(training): score the evaluations"
commit "chore: release 0.6.0"
commit "docs(training): v0.2's results, the 0.5B gains and the 1.5B trades"
printf 'def main():\n    for t in traces:\n        # Messages from rules (lockfiles, generated files) have no attempt.\n        first = t["attempts"][0]["rejected"] if t["attempts"] else None\n        row = {\n            "first_try": first is None,\n        }\n' > training/score.py
printf 'def test_releases():\n    pass\n\n\ndef test_score_reads_rule_messages():\n    """A message from rules (a lockfile) has no attempt; score.py crashed on it."""\n    trace = {"generation": {"source": "rules", "attempts": []}}\n    assert score(trace)["first_try"] == 1.0\n' > training/test_build_inputs.py
git add .
"$BIN" --backend mock --mock-response "test(training): score.py crashes when reading rule messages" \
  --trace "$OUT/conventional-en-fix-as-test.json" >/dev/null

# Found in real use, with smart-commit-0.5b-v0.2: about forty new files shared
# the diff budget, so every section was cut to its header and the prompt
# showed no code; the model took a version from the history ("0.6.0"). The
# prompt now shows the first lines of the files that fit, and only those.
fresh empty-diff
commit "fix(llamacpp): leave room for prompts whose tokens were underestimated"
commit "chore: release 0.6.0"
commit "docs(training): v0.2's results, the 0.5B gains and the 1.5B trades"
mkdir -p training/scenarios/cases training/scenarios/repos
for n in $(seq -w 1 40); do
    case $((10#$n % 3)) in
        0) f="training/scenarios/cases/case-$n.toml" ;;
        1) f="training/scenarios/repos/file-$n.py" ;;
        *) f="training/scenario_$n.py" ;;
    esac
    for i in $(seq 1 30); do printf 'value_%s_%s = "line %s of a new scenario file"\n' "$n" "$i" "$i"; done > "$f"
done
git add .
"$BIN" --backend mock --mock-response "feat(training): add scenarios for the 0.6.0 release" \
  --trace "$OUT/conventional-en-empty-diff.json" >/dev/null

# Prompts the size of real ones, for `smart-commit bench`: a change of one of
# this repository's files, from a pinned commit, sized like the 25th, 50th,
# 75th and 90th percentiles of eval-v1's prompts (the last fills the budget).
# The fixtures above are a few hundred tokens; prefill grows with the
# prompt, so a benchmark on them alone underestimates it.
bench_fixture() {  # NAME COMMIT FILE REPLY
    fresh "bench-$1"
    mkdir -p "$(dirname "$3")"
    for s in "feat(cli): add the eval command" "fix(diff): keep renames in the file list" \
        "docs: describe the hook" "refactor(prompt): share the rules" "test(git): cover empty commits"; do
        commit "$s"
    done
    git -C "$ROOT" show "$2^:$3" > "$3" || { echo "make-traces.sh needs the full history" >&2; exit 1; }
    git add "$3"; commit "feat: add $3"
    git -C "$ROOT" show "$2:$3" > "$3"; git add "$3"
    "$BIN" --backend mock --mock-response "$4" --trace "$OUT/bench-$1.json" >/dev/null
}
bench_fixture p25 21d4671 src/message.rs "fix(generate): retry when the reply repeats a history subject"
bench_fixture p50 ff3e7f3 src/context.rs "feat(context): build the context from recorded data"
bench_fixture p75 cd1ef5c src/context.rs "feat(context): read the ticket from the branch"
bench_fixture p90 482ba4d src/style.rs "feat(style): find where each scope's commits went"
